def compose_resolve_trigger(action_id, clause, trigger_map, parent_map):
    if action_id in trigger_map:
        return trigger_map[action_id]
    current = clause
    while current is not None:
        if current in trigger_map:
            return trigger_map[current]
        current = parent_map.get(current)
    return None

def compose_support_for(keys, support_map):
