def source_actor(raw):
    match = re.search(r'\b([A-Z][A-Za-z]+)\s+(?:agrees|shall|will)\b', raw)
    if match is not None:
        name = match.group(1)
        if name not in ('The', 'Each', 'Neither', 'Receiving'):
            return ['named_recipient', name]
    return ['receiving_party']
